<script setup lang="ts">
import { IconLock } from '@tabler/icons-vue'
definePageMeta({ layout:'console', middleware:'user' })
useSeoMeta({ title:'修改密码 | Zephyr Hub' })
const currentPassword=ref('');const newPassword=ref('');const confirmPassword=ref('');const busy=ref(false);const error=ref('');const session=useState<any>('auth-session')
async function save(){if(newPassword.value!==confirmPassword.value){error.value='两次输入的新密码不一致';return}busy.value=true;error.value='';try{await $fetch('/api/auth/change-password',{method:'POST',body:{currentPassword:currentPassword.value,newPassword:newPassword.value}});if(session.value?.user)session.value.user.mustChangePassword=false;await navigateTo('/console')}catch(value){const failure=value as {data?:{message?:string};message?:string};error.value=failure.data?.message||failure.message||'修改密码失败'}finally{busy.value=false}}
</script>
<template><div class="admin-page"><header class="admin-page__header"><div><span class="admin-kicker">ACCOUNT SECURITY</span><h1>修改密码</h1><p>需要时可更新当前账户密码。</p></div></header><section class="admin-panel" style="max-width:560px"><form class="admin-form" @submit.prevent="save"><label><span>当前密码</span><input v-model="currentPassword" type="password" autocomplete="current-password" required></label><label><span>新密码</span><input v-model="newPassword" type="password" minlength="8" autocomplete="new-password" required></label><label><span>确认新密码</span><input v-model="confirmPassword" type="password" minlength="8" autocomplete="new-password" required></label><p v-if="error" class="form-error">{{ error }}</p><button class="button button--primary" :disabled="busy"><IconLock :size="17" />{{ busy?'保存中':'更新密码' }}</button></form></section></div></template>
